<!doctype html>
<html lang="it">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TubeTV Server Control</title>
<style>
:root{color-scheme:dark;--bg:#07080b;--panel:#111319;--red:#ef233c;--green:#37dc8c;--muted:#8d96a8;--line:#ffffff12}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:#fff;font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}body{min-height:100vh;overflow:hidden;background:radial-gradient(circle at 92% -5%,#40101b 0,transparent 30%),radial-gradient(circle at 0 100%,#0a2330 0,transparent 32%),var(--bg)}.shell{height:100vh;padding:clamp(18px,2.2vw,34px);display:grid;grid-template-rows:auto auto 1fr;gap:20px}.topbar{display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:baseline;gap:13px;font-size:clamp(24px,2.8vw,42px);font-weight:950;letter-spacing:-.06em}.brand b{color:var(--red)}.brand small{font-size:12px;letter-spacing:.16em;color:var(--muted)}.online{display:flex;align-items:center;gap:10px;padding:10px 15px;border:1px solid #37dc8c44;border-radius:99px;background:#37dc8c12;color:#85f4bb;font-weight:850;font-size:13px}.online:before{content:"";width:9px;height:9px;border-radius:50%;background:var(--green);box-shadow:0 0 18px var(--green)}.clock{text-align:right}.clock strong{display:block;font-size:clamp(18px,2vw,28px)}.clock small{color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}.metric{min-width:0;padding:17px 18px;border:1px solid var(--line);border-radius:19px;background:linear-gradient(145deg,#171922df,#0e1016df);box-shadow:0 14px 40px #0003}.metric span{display:block;color:var(--muted);font-size:11px;font-weight:850;text-transform:uppercase;letter-spacing:.1em}.metric strong{display:block;margin-top:8px;font-size:clamp(22px,2.1vw,34px);letter-spacing:-.05em;white-space:nowrap}.metric small{display:block;margin-top:5px;color:#697386;font-size:11px}.main{min-height:0;display:grid;grid-template-columns:minmax(0,1.45fr) minmax(330px,.8fr);gap:16px}.panel{min-height:0;border:1px solid var(--line);border-radius:24px;background:#101219dc;box-shadow:0 22px 70px #0005;overflow:hidden}.panel-head{height:72px;display:flex;align-items:center;justify-content:space-between;padding:0 22px;border-bottom:1px solid var(--line)}.panel-head h2{margin:0;font-size:16px}.panel-head small{color:var(--muted)}.viewers{height:calc(100% - 72px);overflow:hidden;padding:10px}.viewer{display:grid;grid-template-columns:47px minmax(0,1fr) auto;align-items:center;gap:13px;padding:12px;border-radius:16px}.viewer+.viewer{border-top:1px solid #ffffff0b}.avatar{display:grid;width:47px;height:47px;place-items:center;border-radius:14px;background:#ef233c18;color:#ff6275;font-size:20px}.viewer strong,.viewer span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.viewer span{margin-top:4px;color:var(--muted);font-size:12px}.viewer time{color:#59e7a2;font-size:11px;font-weight:800}.empty{height:100%;display:grid;place-items:center;text-align:center;color:var(--muted)}.empty i{display:grid;width:68px;height:68px;margin:0 auto 16px;place-items:center;border-radius:22px;background:#ffffff08;font-style:normal;font-size:28px}.flow{display:grid;grid-template-rows:1fr auto;height:calc(100% - 72px);padding:20px}.chart{position:relative;min-height:170px;border-radius:18px;background:linear-gradient(180deg,#ef233c0b,transparent),repeating-linear-gradient(0deg,transparent 0 39px,#ffffff08 40px)}canvas{position:absolute;inset:0;width:100%;height:100%}.flow-values{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding-top:16px}.flow-value{padding:16px;border-radius:17px;background:#ffffff07}.flow-value span{color:var(--muted);font-size:11px;text-transform:uppercase;font-weight:850;letter-spacing:.08em}.flow-value strong{display:block;margin-top:8px;font-size:25px}.down strong{color:#57d8ff}.up strong{color:#ff6072}@media(max-width:1000px){.metrics{grid-template-columns:repeat(3,1fr)}.main{grid-template-columns:1fr 360px}}@media(max-width:760px){body{overflow:auto}.shell{height:auto;min-height:100vh}.metrics{grid-template-columns:repeat(2,1fr)}.main{grid-template-columns:1fr}.panel{min-height:390px}.clock{display:none}}
</style>
</head>
<body><main class="shell">
<header class="topbar"><div class="brand"><span><b>TUBE</b>TV</span><small>SERVER CONTROL</small></div><div style="display:flex;align-items:center;gap:18px"><div class="online" id="status">SERVER ONLINE</div><div class="clock"><strong id="clock">--:--</strong><small id="date">Caricamento…</small></div></div></header>
<section class="metrics">
<article class="metric"><span>CPU</span><strong id="cpu">--%</strong><small id="load">carico --</small></article><article class="metric"><span>Memoria</span><strong id="ram">--%</strong><small id="ramDetail">-- / --</small></article><article class="metric"><span>Disco server</span><strong id="disk">--%</strong><small id="diskDetail">-- liberi</small></article><article class="metric"><span>Temperatura</span><strong id="temp">--°</strong><small>sensore sistema</small></article><article class="metric"><span>Ping internet</span><strong id="ping">-- ms</strong><small>latenza verso rete</small></article><article class="metric"><span>Spettatori</span><strong id="active">0</strong><small id="sessions">0 sessioni autorizzate</small></article>
</section>
<section class="main"><article class="panel"><div class="panel-head"><h2>Dispositivi e contenuti in riproduzione</h2><small id="updated">Aggiornamento live</small></div><div class="viewers" id="viewers"></div></article><article class="panel"><div class="panel-head"><h2>Traffico in tempo reale</h2><small id="uptime">Uptime --</small></div><div class="flow"><div class="chart"><canvas id="chart"></canvas></div><div class="flow-values"><div class="flow-value down"><span>Download</span><strong id="down">0 Mb/s</strong></div><div class="flow-value up"><span>Upload</span><strong id="up">0 Mb/s</strong></div></div></div></article></section>
</main>
<script>
const $=id=>document.getElementById(id),historyDown=[],historyUp=[];
const bytes=value=>{const units=['B','KB','MB','GB','TB'];let size=Math.max(0,+value||0),i=0;while(size>=1024&&i<4){size/=1024;i++}return size.toFixed(i>1?1:0)+' '+units[i]},rate=value=>((+value||0)*8/1e6).toFixed(2)+' Mb/s',duration=s=>{s=Math.max(0,+s||0);const d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60);return(d?d+'g ':'')+h+'h '+m+'m'},esc=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function draw(){const c=$('chart'),r=c.getBoundingClientRect(),q=devicePixelRatio||1;c.width=r.width*q;c.height=r.height*q;const x=c.getContext('2d'),sets=[[historyDown,'#57d8ff'],[historyUp,'#ef4056']],max=Math.max(1,...historyDown,...historyUp);x.lineWidth=2.5*q;x.lineJoin='round';sets.forEach(([v,color])=>{if(v.length<2)return;x.beginPath();v.forEach((n,i)=>{const px=i/59*c.width,py=c.height-n/max*c.height*.78-c.height*.1;i?x.lineTo(px,py):x.moveTo(px,py)});x.strokeStyle=color;x.shadowColor=color;x.shadowBlur=10*q;x.stroke();x.shadowBlur=0})}
function viewers(items){if(!items.length){$('viewers').innerHTML='<div class="empty"><div><i>◉</i><strong>Nessuna riproduzione attiva</strong><p>Quando un dispositivo avvia un canale comparirà qui.</p></div></div>';return}$('viewers').innerHTML=items.map(v=>`<div class="viewer"><div class="avatar">TV</div><div><strong>${esc(v.channel)}</strong><span>${esc(v.device)} · ${esc(v.group)} · ${esc(v.ip||'rete privata')}</span></div><time>${v.live?'IN ONDA':'RECENTE'}</time></div>`).join('')}
async function refresh(){try{const response=await fetch('/api/dashboard-stats.php?ts='+Date.now(),{cache:'no-store'}),data=await response.json();if(!response.ok||!data.ok)throw 0;const s=data.server,n=data.network,t=data.streaming,ram=s.memoryTotal?s.memoryUsed/s.memoryTotal*100:0,disk=s.diskTotal?s.diskUsed/s.diskTotal*100:0;$('status').textContent='SERVER ONLINE';$('cpu').textContent=s.cpuPercent.toFixed(0)+'%';$('load').textContent='carico '+s.load[0];$('ram').textContent=ram.toFixed(0)+'%';$('ramDetail').textContent=bytes(s.memoryUsed)+' / '+bytes(s.memoryTotal);$('disk').textContent=disk.toFixed(0)+'%';$('diskDetail').textContent=bytes(s.diskTotal-s.diskUsed)+' liberi';$('temp').textContent=s.temperature==null?'N/D':s.temperature.toFixed(0)+'°';$('ping').textContent=s.pingMs==null?'N/D':s.pingMs.toFixed(0)+' ms';$('active').textContent=t.activeViewers;$('sessions').textContent=t.sessions+' sessioni autorizzate';$('down').textContent=rate(n.downloadBps);$('up').textContent=rate(n.uploadBps);$('uptime').textContent='Uptime '+duration(s.uptime);$('updated').textContent='Aggiornato ora';historyDown.push(n.downloadBps);historyUp.push(n.uploadBps);if(historyDown.length>60)historyDown.shift();if(historyUp.length>60)historyUp.shift();draw();viewers(t.viewers||[])}catch(e){$('status').textContent='CONNESSIONE PERSA';$('updated').textContent='Riconnessione…'}}
function tick(){const n=new Date;$('clock').textContent=n.toLocaleTimeString('it-IT');$('date').textContent=n.toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'})}tick();refresh();setInterval(tick,1000);setInterval(refresh,2000);addEventListener('resize',draw);
</script></body></html>
